   686  // the hash function is a simple load and rotate
   687  // algorithm borrowed
   688  int HashMgr::hash(const char* word) const {
   689    unsigned long hv = 0;
   690    for (int i = 0; i < 4 && *word != 0; i++)
   691      hv = (hv << 8) | (*word++);
   692    while (*word != 0) {
   693      ROTATE(hv, ROTATE_LEN);
   694      hv ^= (*word++);
   695    }
   696    return (unsigned long)hv % tableptr.size();
   697  }
